import java.util.*;public final class CachedUserRepository{private final UserStore store;private final UserCache cache;public CachedUserRepository(UserStore s,UserCache c){store=s;cache=c;}public Optional<User>find(String id){return store.find(id);}public void save(User u){cache.put(u.id(),Optional.of(u));store.save(u);}public void delete(String id){cache.evict(id);store.delete(id);}}